const LIMIT = 1200;
// change field if needed
const text = String($input.first().json.message).trim();

if (!text) {
  return [{ json: { message: '' } }];
}

if (text.length <= LIMIT) {
  return [{ json: { message: text, part: 1, total_parts: 1 } }];
}

// try to split nicely before limit
let splitAt = text.lastIndexOf('\n', LIMIT);
if (splitAt < 800) {
  splitAt = text.lastIndexOf(' ', LIMIT);
}
if (splitAt < 800) {
  splitAt = LIMIT;
}

const part1 = text.slice(0, splitAt).trim();
const part2 = text.slice(splitAt).trim();

return [
  { json: { message: part1, part: 1, total_parts: 2 } },
  { json: { message: part2, part: 2, total_parts: 2 } },
];
